const validators = {
  email:    (value) => /\S+@\S+\.\S+/.test(value),
  phone:    (value) => /^\d{10,11}$/.test(value),
  required: (value) => value.trim().length > 0,
}

function validate(value, type) {
  return validators[type](value);
}

