  card:   (amount) => processCard(amount),
  kakao:  (amount) => processKakao(amount),
  toss:   (amount) => processToss(amount),
}

function pay(amount, method) {
  return paymentStrategies[method](amount);
}

// 3. React — 조건부 렌더링 전략
const renderStrategies = {
  loading: () => <Spinner />,
  error:   () => <ErrorMessage />,
  empty:   () => <EmptyState />,
  data:    (data) => <DataList data={data} />,
}

function DataView({ status, data }) {
  return renderStrategies[status]?.(data) ?? null
}

